"""Edge-case tests for the compare-dodge subsystem (GH #42) — generated by bug-hunter agent.

Targets the dodge-by-model ``compare=`` builders in
``src/ferrum/plots/explanation.py`` (``_importance_chart_compare_from_source``,
``_shap_bar_chart_compare_from_source``), ``src/ferrum/plots/model_selection.py``
(``_cv_scores_chart_compare_from_source``), the shared helpers in
``src/ferrum/plots/_helpers.py`` (``_resolve_source``, ``_order_compare_rows``),
``src/ferrum/diagnostics/sources/_compared.py`` (``ComparedModelSource``), and
the GH #42 dodge-eligibility extensions in ``src/ferrum/position.py``.

Fake ``ModelSource``-shaped objects are wrapped in a real
``ComparedModelSource`` so adversarial derived-data frames (NaN/inf
importances, tied scores, mismatched feature sets, degenerate fold counts)
flow through the genuine public dispatch (``importance_chart(cms)`` routes via
``_resolve_source``'s ``isinstance(model, ComparedModelSource)`` passthrough
and ``ComparedModelSource.__getattr__`` auto-dispatch).
"""

from __future__ import annotations

import json

import polars as pl
import pytest

import ferrum
from ferrum.diagnostics.sources._compared import ComparedModelSource
from ferrum.position import Dodge
from tests.fixtures import load_dataset, load_fixture


# ---------------------------------------------------------------------------
# Fakes — minimal ModelSource-shaped objects for ComparedModelSource dispatch
# ---------------------------------------------------------------------------


class FakeImportanceSource:
    """Implements the ``importances(method=, random_state=)`` surface the
    importance compare builder reaches through ``ComparedModelSource.stack``."""

    def __init__(self, rows: dict[str, tuple[float, float]]):
        self._rows = rows

    def importances(self, *, method="builtin", random_state=None, **_):
        feats = list(self._rows.keys())
        return pl.DataFrame(
            {
                "feature": feats,
                "importance": [self._rows[f][0] for f in feats],
                "std": [self._rows[f][1] for f in feats],
                "rank": list(range(1, len(feats) + 1)),
            }
        )


class FakeCVSource:
    """Implements ``cv_scores(cv=, scoring=)`` with a caller-controlled frame,
    so per-model fold counts / adversarial scores can diverge (the real
    ``ModelSource.compare`` path always passes one ``cv`` to every model)."""

    def __init__(self, scores_by_split: dict[str, list[float]]):
        self._s = scores_by_split

    def cv_scores(self, *, cv=5, scoring=None, **_):
        rows = []
        for split, scores in self._s.items():
            for fold, s in enumerate(scores):
                rows.append({"fold": fold, "split": split, "score": s})
        return pl.DataFrame(rows)


class FakeShapSource:
    """Implements ``shap_values(background=)`` for the shap_bar compare
    builder, which stacks via ``ComparedModelSource.stack`` after class
    selection (``_shap_bar_chart_compare_from_source``)."""

    def __init__(self, samples: list[dict[str, float]]):
        self._samples = samples

    def shap_values(self, *, background=None, **_):
        rows = []
        for s, per_feat in enumerate(self._samples):
            for f, v in per_feat.items():
                rows.append(
                    {
                        "sample_id": s,
                        "feature": f,
                        "shap_value": v,
                        "feature_value": 0.0,
                        "feature_value_normalized": 0.0,
                        "class_label": "target",
                    }
                )
        return pl.DataFrame(rows)


def _importance_cms(**models: dict[str, tuple[float, float]]) -> ComparedModelSource:
    return ComparedModelSource({name: FakeImportanceSource(rows) for name, rows in models.items()})


_REG_FEATURES = ["f0", "f1", "f2", "f3", "f4"]


def _reg_setup():
    df = load_dataset("regression")
    return (
        df.select(_REG_FEATURES),
        df["y"],
        load_fixture("regression_ridge"),
        load_fixture("regression_rf"),
    )


# ---------------------------------------------------------------------------
# Null / NaN
# ---------------------------------------------------------------------------


def test_nan_importance_compare_renders_without_nan_token():
    """A NaN importance flows through ``_importance_bounds_and_domain``
    (explanation.py:76-90); the ``upper_max > 0`` guard must keep the NaN
    out of the value-axis domain and the SVG must carry no NaN coordinate."""
    cms = _importance_cms(
        a={"f1": (float("nan"), 0.0), "f2": (0.5, 0.1)},
        b={"f1": (0.3, 0.0), "f2": (0.4, 0.1)},
    )
    svg = ferrum.importance_chart(cms).to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


# FIXED (GH #76): a feature whose importance was NaN got a NaN _rank_score;
# polars sorts NaN above every real score in a descending rank sort, so the
# NaN feature hijacked the #1 slot and displaced a real feature ('small')
# from top_k=2. Fixed by fill_nan(None) + nulls_last=True in
# _importance_chart_compare_from_source's ranking (explanation.py).
def test_nan_importance_must_not_displace_real_features_in_top_k():
    """Global ranking (explanation.py:212-219) uses ``abs().mean()`` which
    propagates NaN; a NaN-scored feature must not outrank real features."""
    cms = _importance_cms(
        a={"good": (0.9, 0.0), "nanfeat": (float("nan"), 0.0), "small": (0.1, 0.0)},
        b={"good": (0.8, 0.0), "nanfeat": (float("nan"), 0.0), "small": (0.2, 0.0)},
    )
    chart = ferrum.importance_chart(cms, top_k=2)
    kept = set(chart._data["feature"].unique().to_list())
    assert kept == {"good", "small"}, (
        f"NaN-scored feature displaced a real feature from the global top-k: kept={kept}"
    )


def test_cv_scores_compare_nan_score_renders_without_nan_token():
    """A NaN fold score reaches the BoxStats transform behind
    ``_cv_scores_chart_compare_from_source`` (model_selection.py:241-256);
    the rendered SVG must not carry NaN coordinates."""
    cms = ComparedModelSource(
        {
            "a": FakeCVSource({"train": [0.9, float("nan"), 0.92], "test": [0.8, 0.81, 0.82]}),
            "b": FakeCVSource({"train": [0.7, 0.72, 0.71], "test": [0.6, 0.62, 0.61]}),
        }
    )
    svg = ferrum.cv_scores_chart(cms).to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


# ---------------------------------------------------------------------------
# Empty inputs
# ---------------------------------------------------------------------------


# FIXED (GH #76): top_k=0 used to empty the frame before
# _importance_bounds_and_domain (explanation.py:86: float(df["imp_upper"].max())
# -> float(None)), raising `TypeError: float() argument must be ... not
# 'NoneType'` instead of a legible ValueError. Fixed by validating
# top_k >= 1 (or None) once in importance_chart() -- the shared choke point
# for both the single-model and compare-by-model builder paths -- via
# _require_positive (plots/_helpers.py).
def test_importance_compare_top_k_zero_raises_legible_error():
    cms = _importance_cms(a={"f1": (0.1, 0.0)}, b={"f1": (0.2, 0.0)})
    with pytest.raises(ValueError):
        ferrum.importance_chart(cms, top_k=0)


# FIXED (GH #76 cohesion gate): max_display=0 on the SHAP entries used to
# crash pre-#76 and would have silently rendered an empty chart post-#76
# (once _zero_anchored_domain tolerated an empty series) -- asymmetric with
# the top_k=0 guard above. All four public SHAP entries now validate
# max_display >= 1 (or None) via the same _require_positive choke point.
def test_shap_max_display_zero_raises_legible_error():
    X, y, ridge, _ = _reg_setup()
    for func in (
        ferrum.shap_bar_chart,
        ferrum.shap_beeswarm_chart,
        ferrum.shap_chart,
    ):
        with pytest.raises(ValueError, match="max_display"):
            func(ridge, X, y, max_display=0)
    with pytest.raises(ValueError, match="max_display"):
        ferrum.shap_waterfall_chart(ridge, X, y, sample_idx=0, max_display=0)


def test_empty_compare_dict_renders_single_model_dodge_chart():
    """``compare={}`` is not None, so ``_resolve_source`` (helpers.py:566-576)
    builds ``{"base": model}`` — a one-model ComparedModelSource must survive
    the dodge builders (single dodge group) for importance and cv_scores."""
    from ferrum.chart import Chart

    X, y, ridge, _ = _reg_setup()
    c1 = ferrum.importance_chart(ridge, X, y, compare={})
    assert isinstance(c1, Chart)
    assert c1._data["model"].unique().to_list() == ["base"]
    svg1 = c1.to_svg()
    assert "<svg" in svg1 and "NaN" not in svg1

    c2 = ferrum.cv_scores_chart(ridge, X, y, cv=3, compare={})
    assert isinstance(c2, Chart)
    assert "<svg" in c2.to_svg()


