def test_single_entry_compared_source_importance_renders():
    """A one-model ComparedModelSource routed straight through the public
    dispatcher (explanation.py:871-872) exercises Dodge with n_groups=1."""
    cms = _importance_cms(only={"f1": (0.4, 0.1), "f2": (0.5, 0.1)})
    svg = ferrum.importance_chart(cms).to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_cv_scores_compare_single_fold_per_model_renders():
    """One fold per (split, model): BoxStats over a single value collapses
    q1=median=q3 — the degenerate box must render without NaN geometry."""
    cms = ComparedModelSource(
        {
            "a": FakeCVSource({"train": [0.9], "test": [0.8]}),
            "b": FakeCVSource({"train": [0.7], "test": [0.6]}),
        }
    )
    svg = ferrum.cv_scores_chart(cms).to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_cv_scores_compare_strip_single_model_renders():
    """kind='strip' with one model: the jitter-drop path (desugar_cv_scores
    color_field branch) plus Dodge n_groups=1 must still place fold points."""
    cms = ComparedModelSource({"only": FakeCVSource({"train": [0.9, 0.91], "test": [0.8, 0.81]})})
    svg = ferrum.cv_scores_chart(cms, kind="strip").to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_text_dodge_single_group_renders_labels():
    """GH #42 made ``text`` dodge-eligible (position.py:_DODGE_ELIGIBLE);
    the degenerate one-group dodge must not zero out text anchors."""
    df = pl.DataFrame({"x": ["a", "b"], "y": [1.0, 2.0], "g": ["u", "u"], "t": ["p", "q"]})
    svg = ferrum.Chart(df).mark_text(position=Dodge(by="g")).encode(x="x", y="y", text="t").to_svg()
    assert ">p<" in svg and ">q<" in svg
    assert "NaN" not in svg


