def test_seven_model_compare_renders_all_model_legend_entries():
    """Many (7) dodge sub-bands per feature band: every registered model name
    must survive into the legend (color domain from encounter order)."""
    names = [f"mdl{i}" for i in range(7)]
    cms = ComparedModelSource(
        {
            name: FakeImportanceSource({"f1": (0.05 + 0.1 * i, 0.0), "f2": (0.2, 0.0)})
            for i, name in enumerate(names)
        }
    )
    svg = ferrum.importance_chart(cms).to_svg()
    assert "NaN" not in svg
    for name in names:
        assert f">{name}<" in svg, f"model {name!r} missing from legend"


def test_mismatched_feature_sets_render_union_not_intersection():
    """Models fitted on different feature sets (only constructible by wrapping
    heterogeneous sources directly): the global ranking (explanation.py:212-219)
    groups over the union; a feature missing from one model simply has no bar,
    and the render must survive the absent (feature, model) combinations."""
    cms = _importance_cms(
        a={"f1": (0.9, 0.0), "f2": (0.5, 0.0)},
        b={"f2": (0.4, 0.0), "f3": (0.8, 0.0)},
    )
    chart = ferrum.importance_chart(cms)
    assert sorted(chart._data["feature"].unique().to_list()) == ["f1", "f2", "f3"]
    assert chart._data.height == 4  # f1@a, f2@a, f2@b, f3@b — union, not intersection
    svg = chart.to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


# FIXED (GH #76): _resolve_source used to build `{"base": model, **compare}`
# (helpers.py:570), so compare={"base": other} silently OVERWROTE the primary
# model -- the chart rendered only `other`'s importances labeled "base" and
# the model the user passed positionally was discarded without any warning
# or error. Fixed by rejecting the reserved "base" compare= key with a
# legible ValueError in _resolve_source.
def test_compare_base_key_collision_must_not_silently_discard_primary():
    X, y, ridge, rf = _reg_setup()
    with pytest.raises(ValueError):
        ferrum.importance_chart(ridge, X, y, compare={"base": rf})


def test_cv_scores_compare_mismatched_fold_counts_render():
    """Models with different fold counts (5 vs 3) produce unequal dodge-group
    sizes per split band; BoxStats must aggregate each group independently."""
    cms = ComparedModelSource(
        {
            "a": FakeCVSource(
                {"train": [0.9, 0.91, 0.92, 0.93, 0.94], "test": [0.8, 0.81, 0.82, 0.83, 0.84]}
            ),
            "b": FakeCVSource({"train": [0.7, 0.72, 0.71], "test": [0.6, 0.62, 0.61]}),
        }
    )
    svg = ferrum.cv_scores_chart(cms).to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


# ---------------------------------------------------------------------------
# Sort-order stability
# ---------------------------------------------------------------------------


# FIXED (GH #76): the global feature ranking (explanation.py:212-216) used to
# be group_by("feature") (unordered, hash-partitioned) followed by an
# unstable sort on "_rank_score"; with tied scores the top_k cut and the
# feature-axis order differed run to run (observed: 6 distinct orders in 6
# builds), violating the determinism contract the suite pins elsewhere
# (test_importance_compare_deterministic passes only because real fixture
# data has no ties). Fixed by group_by(maintain_order=True) plus a
# feature-name secondary sort key, so tied scores resolve to a fixed order.
def test_importance_compare_tied_scores_deterministic_feature_order():
    orders = set()
    for _ in range(8):
        cms = _importance_cms(
            **{m: {f"f{i}": (0.5, 0.0) for i in range(8)} for m in ("a", "b", "c")}
        )
        chart = ferrum.importance_chart(cms, top_k=4, show_values=False)
        orders.add(tuple(chart._data["feature"].unique(maintain_order=True).to_list()))
    assert len(orders) == 1, (
        f"tied importances produced {len(orders)} distinct feature orders across "
        f"8 identical builds: {orders}"
    )


# FIXED (GH #76): same unstable group_by + sort idiom in
# _shap_order_features (explanation.py:294-299) -- tied |SHAP| scores made
# the shared top-k feature set and axis order nondeterministic (observed: 8
# distinct orders in 8 builds of the shap_bar compare chart). Fixed by the
# same group_by(maintain_order=True) + feature-name-tiebreak sort as the
# importance ranking above (this helper is shared by the single-model
# beeswarm/bar/waterfall builders too).
def test_shap_bar_compare_tied_scores_deterministic_feature_order():
    orders = set()
    for _ in range(8):
        cms = ComparedModelSource(
            {
                "a": FakeShapSource([{f"f{i}": 0.5 for i in range(8)}]),
                "b": FakeShapSource([{f"f{i}": 0.5 for i in range(8)}]),
            }
        )
        chart = ferrum.shap_bar_chart(cms, max_display=4)
        orders.add(tuple(chart._data["feature"].unique(maintain_order=True).to_list()))
    assert len(orders) == 1, (
        f"tied |SHAP| scores produced {len(orders)} distinct feature orders across "
        f"8 identical builds: {orders}"
    )


