def test_feature_value_named_model_renders():
    """A feature literally named 'model' collides with the stamped model
    column's *name* only as a band-axis value — the Enum casts in
    _order_compare_rows (helpers.py:505-509) and the color/x encodings must
    keep the two namespaces apart."""
    cms = _importance_cms(
        a={"model": (0.9, 0.0), "f2": (0.5, 0.0)},
        b={"model": (0.3, 0.0), "f2": (0.4, 0.0)},
    )
    chart = ferrum.importance_chart(cms)
    assert set(chart._data["feature"].unique().to_list()) == {"model", "f2"}
    svg = chart.to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_feature_named_dodge_metadata_key_renders():
    """A feature named '__dodge_n_groups__' (the Rust schema-metadata key,
    position.rs:DODGE_N_GROUPS_KEY) as a *band value* must not perturb the
    dodge group count."""
    cms = _importance_cms(
        a={"__dodge_n_groups__": (0.9, 0.0), "f2": (0.5, 0.0)},
        b={"__dodge_n_groups__": (0.3, 0.0), "f2": (0.4, 0.0)},
    )
    svg = ferrum.importance_chart(cms).to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_user_column_named_dodge_metadata_key_is_inert():
    """A user data *column* named '__dodge_n_groups__' shares its name with
    the Arrow schema-metadata key Dodge stamps (archaeology doc flags this
    metadata as fragile). The column must be inert: byte-identical output
    with and without it."""
    base = {"x": ["a", "a", "b", "b"], "y": [1.0, 2.0, 3.0, 4.0], "g": ["u", "v", "u", "v"]}
    without = (
        ferrum.Chart(pl.DataFrame(base))
        .mark_bar(position=Dodge(by="g"))
        .encode(x="x", y="y", color="g")
        .to_svg()
    )
    with_col = (
        ferrum.Chart(pl.DataFrame({**base, "__dodge_n_groups__": [9, 9, 9, 9]}))
        .mark_bar(position=Dodge(by="g"))
        .encode(x="x", y="y", color="g")
        .to_svg()
    )
    assert with_col == without


# ---------------------------------------------------------------------------
# Spec round-trips
# ---------------------------------------------------------------------------


def test_compare_dodge_position_roundtrips_through_spec_json():
    """The chart-level Dodge(by='model') must survive to_spec -> JSON ->
    ChartSpec.from_json -> JSON with padding and by intact (position.py
    to_spec_dict + Rust serde round-trip)."""
    from ferrum._core import ChartSpec

    cms = _importance_cms(
        a={"f1": (0.4, 0.0), "f2": (0.5, 0.1)},
        b={"f1": (0.3, 0.0), "f2": (0.4, 0.1)},
    )
    chart = ferrum.importance_chart(cms)
    spec_json = chart.to_spec().to_json()
    pos = json.loads(spec_json).get("position")
    assert pos == {"type": "dodge", "by": "model", "padding": 0.05}
    rt = json.loads(ChartSpec.from_json(spec_json).to_json()).get("position")
    assert rt == pos


