def test_orient_validated_before_source_resolution():
    """importance_chart validates orient (explanation.py:855) before
    _resolve_source runs, so compare= and non-compare calls reject a bad
    orient identically — even with garbage model objects."""
    with pytest.raises(ValueError, match="orient"):
        ferrum.importance_chart(object(), None, None, orient="diagonal", compare={"a": object()})
    with pytest.raises(ValueError, match="orient"):
        ferrum.importance_chart(object(), None, None, orient="diagonal")


def test_text_dodge_missing_by_column_warns_and_renders():
    """Dodge(by=<absent column>) on a text mark (GH #42 eligibility) must warn
    legibly and render un-offset rather than crash or silently mis-place."""
    df = pl.DataFrame({"x": ["a", "b"], "y": [1.0, 2.0], "t": ["p", "q"]})
    chart = ferrum.Chart(df).mark_text(position=Dodge(by="nope")).encode(x="x", y="y", text="t")
    with pytest.warns(UserWarning, match="dodge could not be applied"):
        svg = chart.to_svg()
    assert ">p<" in svg and ">q<" in svg


def test_compare_dict_key_with_xml_hostile_name_produces_wellformed_svg():
    """Model names land in legend <text> content; XML-special characters
    ('<', '&') must be entity-escaped or the SVG is unparseable. Asserted
    structurally (raw markup absent, escaped form present) rather than via an
    XML parser."""
    cms = _importance_cms(
        **{
            'm<&"1': {"f1": (0.4, 0.0), "f2": (0.5, 0.1)},
            "b": {"f1": (0.3, 0.0), "f2": (0.4, 0.1)},
        }
    )
    svg = ferrum.importance_chart(cms).to_svg()
    assert "m<&" not in svg, "unescaped XML-special characters leaked into the SVG"
    assert "m&lt;&amp;" in svg, "escaped legend label for the hostile model name is missing"
